"""P10 architecture self-check — deep audit script"""
import os, re, json, sys
from pathlib import Path

SKILLS_DIR = os.path.expanduser("~/.hermes/skills")
STAGING_DIR = os.path.expanduser("~/.hermes/skills-staging")
MCP_DIR = os.path.expanduser("~/.hermes/mcp/proposals")
CRON_FILE = os.path.expanduser("~/.hermes/cron/jobs.json")
EVOLVE_LOG = os.path.expanduser("~/.hermes/logs/evolve.log")

results = {}

# ── 1. Skill Bloat Audit ──
skill_count = 0
small_skills = []
empty_skills = []
all_skills = {}
for root, dirs, files in os.walk(SKILLS_DIR):
    for f in files:
        if f == 'SKILL.md':
            path = os.path.join(root, f)
            sz = os.path.getsize(path)
            skill_count += 1
            rel = path.replace(SKILLS_DIR + '/', '')
            try:
                with open(path) as fh:
                    content = fh.read()
                name_match = re.search(r'^name:\s*(\S+)', content, re.MULTILINE)
                name = name_match.group(1) if name_match else rel
                body = content.split('---', 2)[-1].strip() if content.startswith('---') else content
                all_skills[name] = {'path': rel, 'size': sz, 'body_len': len(body)}
                if sz < 200:
                    small_skills.append((name, sz, rel))
                if len(body) < 50:
                    empty_skills.append((name, sz, rel))
            except:
                all_skills[rel] = {'path': rel, 'size': sz, 'body_len': 0}

# ── 2. Skill Dependency Analysis ──
refs = {}
for name, info in all_skills.items():
    try:
        with open(os.path.join(SKILLS_DIR, info['path'])) as fh:
            content = fh.read()
        deps = re.findall(r'skill_view\(\s*[\'"]([^\'"]*?)[\'"]', content)
        refs[name] = len(deps)
    except:
        refs[name] = 0

total_refs = len(refs)
avg_refs = sum(refs.values()) / len(refs) if refs else 0
max_ref = max(refs.values(), default=0)
max_ref_names = [k for k, v in refs.items() if v == max_ref]

# ── 3. Orphan Skills (never cited) ──
cited = set()
for name, info in all_skills.items():
    try:
        with open(os.path.join(SKILLS_DIR, info['path'])) as fh:
            content = fh.read()
        deps = re.findall(r'skill_view\(\s*[\'"]([^\'"]*?)[\'"]', content)
        cited.update(deps)
    except:
        pass
orphans = set(all_skills.keys()) - cited
# Remove self-citations
orphans_final = set()
for o in orphans:
    has_deps = refs.get(o, 0) > 0
    if not has_deps:
        orphans_final.add(o)

# ── 4. Cron Health ──
cron_status = {}
try:
    with open(CRON_FILE) as fh:
        jobs = json.load(fh)
    never_run = []
    for j in jobs:
        jid = j.get('job_id', '?')
        name = j.get('name', '?')
        last = j.get('last_run_at')
        status = j.get('last_status')
        enabled = j.get('enabled', True)
        if not last and enabled:
            never_run.append({'id': jid, 'name': name, 'schedule': j.get('schedule', '?')})
    cron_status['total'] = len(jobs)
    cron_status['never_run'] = len(never_run)
    cron_status['never_run_list'] = never_run
except Exception as e:
    cron_status['error'] = str(e)

# ── 5. Staging/Canary ──
staging_status = {}
try:
    staging_files = list(Path(STAGING_DIR).rglob('*'))
    staging_status['files'] = len(staging_files)
    staging_status['list'] = [str(f.relative_to(STAGING_DIR)) for f in staging_files if f.is_file()][:20]
except:
    staging_status['exists'] = False

# ── 6. MCP Proposals ──
mcp_status = {}
try:
    mcp_files = list(Path(MCP_DIR).glob('*.md'))
    mcp_status['proposals'] = len(mcp_files)
    mcp_status['list'] = [f.name for f in mcp_files]
except:
    mcp_status['exists'] = False

# ── 7. Evolve log analysis ──
evolve_analysis = {}
try:
    with open(EVOLVE_LOG) as fh:
        lines = [l.strip() for l in fh if l.strip()]
    kept = sum(1 for l in lines if '"eval_result": "kept"' in l)
    rolled = sum(1 for l in lines if '"eval_result": "rolled_back"' in l)
    pending = sum(1 for l in lines if '"eval_result": "pending"' in l)
    degraded = sum(1 for l in lines if '"degraded": true' in l)
    evolve_analysis = {'total': len(lines), 'kept': kept, 'rolled_back': rolled,
                       'pending': pending, 'degraded': degraded}
except Exception as e:
    evolve_analysis['error'] = str(e)

# ── Output ──
report = {
    'skill_bloat': {
        'total': skill_count,
        'small_under_200b': len(small_skills),
        'small_list': [{'name': n, 'size': s, 'path': p} for n, s, p in small_skills[:15]],
        'empty_body': len(empty_skills),
        'empty_list': [{'name': n, 'path': p} for n, s, p in empty_skills[:10]],
    },
    'skill_deps': {
        'total_analyzed': total_refs,
        'avg_refs': round(avg_refs, 1),
        'max_refs': max_ref,
        'max_ref_skills': max_ref_names,
        'orphans_count': len(orphans_final),
        'orphans_sample': sorted(list(orphans_final))[:30],
    },
    'cron_health': cron_status,
    'staging': staging_status,
    'mcp_proposals': mcp_status,
    'evolve_log': evolve_analysis,
}

print(json.dumps(report, indent=2))
"}

