from hermes_tools import terminal
import json, re

# Get cron jobs
r = terminal("cat ~/.hermes/cron/jobs.json 2>/dev/null", timeout=10)
jobs = json.loads(r['output'])['jobs']

print("=== 11 CRON JOBS — SCHEDULE HEATMAP ===")
print()

# Parse schedules and build heatmap
hours = {h: [] for h in range(24)}

for j in jobs:
    name = j.get('name', '?')
    sched = j.get('schedule', {})
    if isinstance(sched, dict):
        expr = sched.get('expr', '?')
    else:
        expr = str(sched)
    enabled = j.get('enabled', True)

    # Parse cron expression to find hours
    parts = expr.split()
    if len(parts) >= 5:
        hour_field = parts[1]  # minute hour dom month dow
        # Handle */N, comma-separated, single values
        active_hours = []
        if hour_field == '*':
            active_hours = list(range(24))
        elif hour_field.startswith('*/'):
            step = int(hour_field[2:])
            active_hours = list(range(0, 24, step))
        elif ',' in hour_field:
            active_hours = [int(h) for h in hour_field.split(',')]
        else:
            try:
                active_hours = [int(hour_field)]
            except:
                active_hours = []

        for h in active_hours:
            hours[h].append({
                'name': name[:40],
                'minute': parts[0],
                'enabled': enabled,
                'id': j.get('id', '?')[:8]
            })

# Print heatmap
print("Hour | Jobs | Status")
print("-" * 70)
for h in range(24):
    jobs_here = hours[h]
    count = len(jobs_here)
    bar = '█' * min(count, 10) + '░' * max(0, 10 - count)
    status = ''
